        case PLANS.MAIL:
            return ADDON_NAMES.MEMBER_SCRIBE_MAILPLUS;
        case PLANS.DRIVE:
            return ADDON_NAMES.MEMBER_SCRIBE_DRIVEPLUS;
        case PLANS.BUNDLE:
            return ADDON_NAMES.MEMBER_SCRIBE_BUNDLE;
